/* ============================================================
   MediaFlow v247 — PWA Install Reliability + Diagnostics
   --------------------------------------------------------------------------
   - Keeps the v246 mobile/tablet PWA UX.
   - Explains native-install availability instead of presenting a dead control.
   - Adds an explicit PWA diagnostics runner and cache repair action.
   - Verifies the deployed manifest, worker, app-shell cache and every local
     app-shell URL so GitHub Pages path/deployment failures are visible.
   - Works with the v247 worker diagnostic/repair message API generated by
     scripts/pwa.py.
   ============================================================ */
const V247_RUNTIME_VERSION=247;
const V247_PWA_DIAGNOSTICS={running:false,lastRunAt:0,report:null,error:''};
const V247_PWA_TIMEOUT=9000;

function v247WithTimeout(promise,ms=V247_PWA_TIMEOUT,label='operation'){
  let timer=0;
  return Promise.race([
    Promise.resolve(promise),
    new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${label} timed out`)),ms);})
  ]).finally(()=>clearTimeout(timer));
}

function v247PwaStateLabel(){
  if(v244PwaStandalone()||V244_PWA_STATE.installed)return {tone:'pass',text:'Installed'};
  if(V244_PWA_STATE.installPrompt)return {tone:'pass',text:'Ready to install'};
  if(!v244PwaSupported())return {tone:'fail',text:'Install unavailable'};
  if(V247_PWA_DIAGNOSTICS.running)return {tone:'info',text:'Testing PWA'};
  const report=V247_PWA_DIAGNOSTICS.report;
  if(report?.status==='fail')return {tone:'fail',text:'Needs attention'};
  if(report?.status==='warn')return {tone:'warn',text:'Checks passed with warnings'};
  if(report?.status==='pass')return {tone:'pass',text:'PWA checks passed'};
  return {tone:'info',text:'PWA registered'};
}

function v247PwaStatus(){
  if(!v244PwaSupported())return 'Install unavailable — MediaFlow must run over HTTPS or localhost.';
  if(V244_PWA_STATE.updateReady)return `MediaFlow v${V247_RUNTIME_VERSION} app update is ready. Reload the app to apply it.`;
  if(v244PwaStandalone()||V244_PWA_STATE.installed)return V244_PWA_STATE.offlineReady?'Installed · service worker active and app shell available.':'Installed as an app.';
  if(V244_PWA_STATE.installPrompt)return V244_PWA_STATE.offlineReady?'Ready to install · Chrome/browser native install prompt is available.':'Ready to install.';
  if(V247_PWA_DIAGNOSTICS.running)return 'Checking manifest, service worker, app-shell cache and deployed PWA assets…';
  if(V247_PWA_DIAGNOSTICS.report?.status==='fail')return `Install needs attention — ${V247_PWA_DIAGNOSTICS.report.summary||'one or more PWA checks failed'}.`;
  if(V244_PWA_STATE.error)return `PWA setup could not finish: ${String(V244_PWA_STATE.error)}`;
  if(V247_PWA_DIAGNOSTICS.report?.status==='pass')return 'PWA technical checks passed. If Chrome still does not show Install, reload once or use the browser Install app menu.';
  if(V247_PWA_DIAGNOSTICS.report?.status==='warn')return 'PWA core checks passed with warnings. Open PWA Diagnostics for the exact install/cache state.';
  if(V244_PWA_STATE.offlineReady)return 'PWA service worker is ready, but the browser has not exposed a native install prompt yet. Run PWA Test for the exact reason.';
  return 'Preparing installable app support…';
}

v244PwaStatus=v247PwaStatus;

function v247DiagBadge(status,text){
  return `<span class="v247-diag-badge is-${status}">${escapeHtml(text)}</span>`;
}
function v247DiagMark(status){
  if(status==='pass')return '✓';
  if(status==='fail')return '×';
  if(status==='warn')return '!';
  return '•';
}
function v247DiagRows(report){
  if(!report)return '<div class="v247-diag-empty">Run the test to verify the live PWA manifest, service worker, cache, icons and every local app-shell asset.</div>';
  return (report.checks||[]).map(row=>`<div class="v247-diag-row is-${row.status}">
    <span class="v247-diag-mark" aria-hidden="true">${v247DiagMark(row.status)}</span>
    <div class="v247-diag-copy"><b>${escapeHtml(row.label)}</b><span>${escapeHtml(row.detail||'')}</span></div>
  </div>`).join('');
}
function v247DiagFailures(report){
  const failed=report?.failedAssets||[];
  if(!failed.length)return '';
  return `<div class="v247-diag-failures"><b>Failed deployed assets</b>${failed.map(item=>`<code>${escapeHtml(item.url||item.asset||'unknown')} — ${escapeHtml(String(item.status||item.error||'failed'))}</code>`).join('')}</div>`;
}
function v247DiagnosticsBodyHtml(){
  const report=V247_PWA_DIAGNOSTICS.report;
  const state=V247_PWA_DIAGNOSTICS.running
    ? v247DiagBadge('info','Running…')
    : report
      ? v247DiagBadge(report.status,report.status==='pass'?'Passed':report.status==='warn'?'Warnings':'Needs attention')
      : v247DiagBadge('info','Not tested');
  const meta=report?`<div class="v247-diag-meta">Worker v${escapeHtml(String(report.workerVersion??'unknown'))} · ${escapeHtml(String(report.cachedCount??0))}/${escapeHtml(String(report.shellCount??0))} shell assets cached · tested ${new Date(report.finishedAt).toLocaleTimeString()}</div>`:'';
  return `<div class="v247-diag-head"><div><b>PWA Diagnostics</b><div class="hint">Checks the live GitHub Pages PWA instead of guessing why a browser refuses installation.</div></div>${state}</div>
    ${meta}
    <div class="v247-diag-grid">${v247DiagRows(report)}</div>
    ${v247DiagFailures(report)}
    ${V247_PWA_DIAGNOSTICS.error?`<div class="v247-diag-error">${escapeHtml(V247_PWA_DIAGNOSTICS.error)}</div>`:''}
    <div class="v247-diag-actions">
      <button id="v247-pwa-test" class="btn btn-sm" data-v225-iconified="1" onclick="App.v247RunPwaDiagnostics()" ${V247_PWA_DIAGNOSTICS.running?'disabled':''}>${V246_PWA_ICONS.update}<span>${V247_PWA_DIAGNOSTICS.running?'Testing…':'Run PWA Test'}</span></button>
      <button id="v247-pwa-repair" class="btn btn-sm btn-ghost" data-v225-iconified="1" onclick="App.v247RepairPwaCache()" ${V247_PWA_DIAGNOSTICS.running?'disabled':''}>${v246PwaIcon('<path d="M12 3v3"/><path d="M12 18v3"/><path d="M3 12h3"/><path d="M18 12h3"/><path d="m5.6 5.6 2.1 2.1"/><path d="m16.3 16.3 2.1 2.1"/><path d="m18.4 5.6-2.1 2.1"/><path d="m7.7 16.3-2.1 2.1"/><circle cx="12" cy="12" r="3"/>')}<span>Repair app cache</span></button>
    </div>`;
}

function v247PwaSettingsHtml(){
  const installed=v244PwaStandalone()||V244_PWA_STATE.installed;
  const state=v247PwaStateLabel();
  const open=V247_PWA_DIAGNOSTICS.report?.status==='fail'||!!V247_PWA_DIAGNOSTICS.error;
  return `<div class="card v244-pwa-card v246-pwa-card v247-pwa-card" style="margin-bottom:22px">
    <div class="v244-pwa-card-main">
      <div class="v244-pwa-mark v246-pwa-mark" aria-hidden="true"><img src="assets/icons/mediaflow-192.png" alt=""></div>
      <div class="v244-pwa-copy">
        <div class="v247-pwa-title-row"><b>Install MediaFlow</b>${v247DiagBadge(state.tone,state.text)}</div>
        <div class="hint">Install MediaFlow as a Progressive Web App on desktop, tablet or mobile. v247 can test the live manifest, worker and every app-shell URL when the browser refuses installation.</div>
        <div id="v244-pwa-status" class="v244-pwa-status">${escapeHtml(v247PwaStatus())}</div>
      </div>
    </div>
    <div class="v244-pwa-actions v246-pwa-actions">
      <button id="v244-pwa-install" class="btn btn-sm btn-primary" data-v225-iconified="1" ${installed?'disabled':''} onclick="App.v244InstallPwa()">${V246_PWA_ICONS.install}<span>${installed?'Installed':'Install app'}</span></button>
      <button id="v244-pwa-update" class="btn btn-sm" data-v225-iconified="1" onclick="App.v246ReloadPwa()">${V246_PWA_ICONS.reload}<span>${V244_PWA_STATE.updateReady?'Reload update':'Reload app'}</span></button>
      <button id="v246-pwa-check" class="btn btn-sm btn-ghost" data-v225-iconified="1" onclick="App.v244CheckPwaUpdate(true)">${V246_PWA_ICONS.update}<span>Check PWA update</span></button>
    </div>
    <details id="v247-pwa-diagnostics" class="v247-pwa-diagnostics" ${open?'open':''}>
      <summary>PWA Diagnostics <span>manifest · service worker · cache · assets</span></summary>
      <div id="v247-pwa-diagnostics-body" class="v247-pwa-diagnostics-body">${v247DiagnosticsBodyHtml()}</div>
    </details>
  </div>`;
}

v244PwaSettingsHtml=v247PwaSettingsHtml;
App.v244PwaSettingsHtml=v244PwaSettingsHtml;

function v247RefreshDiagnosticsDom(){
  const body=document.getElementById('v247-pwa-diagnostics-body');
  if(body)body.innerHTML=v247DiagnosticsBodyHtml();
  const status=document.getElementById('v244-pwa-status');
  if(status)status.textContent=v247PwaStatus();
  const titleRow=document.querySelector('.v247-pwa-title-row');
  if(titleRow){
    const old=titleRow.querySelector('.v247-diag-badge');
    const state=v247PwaStateLabel();
    if(old){
      old.className=`v247-diag-badge is-${state.tone}`;
      old.textContent=state.text;
    }
  }
}

const v247RefreshPwaDomBase=v244RefreshPwaDom;
v244RefreshPwaDom=function(){
  try{v247RefreshPwaDomBase.apply(this,arguments);}catch(_){ }
  v247RefreshDiagnosticsDom();
};

function v247AddCheck(report,label,status,detail){
  report.checks.push({label,status,detail:String(detail||'')});
  if(status==='fail')report.failures++;
  if(status==='warn')report.warnings++;
}

async function v247FetchProbe(url,kind='asset'){
  const absolute=new URL(url,document.baseURI).href;
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),V247_PWA_TIMEOUT);
  try{
    const response=await fetch(absolute,{cache:'no-store',signal:controller.signal,credentials:'same-origin'});
    return {url,absolute,ok:!!response.ok,status:response.status,type:response.type,contentType:response.headers.get('content-type')||'',kind};
  }catch(err){
    return {url,absolute,ok:false,status:0,error:String(err?.message||err||'fetch failed'),kind};
  }finally{clearTimeout(timer);}
}

async function v247MapLimit(items,limit,fn){
  const out=new Array(items.length);let next=0;
  async function worker(){
    while(true){
      const i=next++;if(i>=items.length)return;
      try{out[i]=await fn(items[i],i);}catch(err){out[i]={url:items[i],ok:false,status:0,error:String(err?.message||err||'failed')};}
    }
  }
  await Promise.all(Array.from({length:Math.min(limit,items.length||1)},()=>worker()));
  return out;
}

function v247ResolveManifestUrl(value,manifestUrl){
  try{return new URL(String(value||''),manifestUrl).href;}catch(_){return '';}
}

async function v247WorkerMessage(worker,message,timeout=V247_PWA_TIMEOUT){
  if(!worker||typeof worker.postMessage!=='function')throw new Error('No compatible service worker is available');
  const channel=new MessageChannel();
  const result=new Promise((resolve,reject)=>{
    const timer=setTimeout(()=>reject(new Error('Service worker diagnostic response timed out')),timeout);
    channel.port1.onmessage=event=>{clearTimeout(timer);resolve(event.data||{});};
    channel.port1.onmessageerror=()=>{clearTimeout(timer);reject(new Error('Service worker diagnostic response failed'));};
  });
  worker.postMessage(message,[channel.port2]);
  return result;
}

async function v247GetRegistration(){
  let reg=V244_PWA_STATE.registration;
  if(reg)return reg;
  if(!v244PwaSupported())return null;
  if(!reg)reg=await v244RegisterPwa();
  if(!reg&&navigator.serviceWorker?.getRegistration)reg=await navigator.serviceWorker.getRegistration('./');
  if(reg)V244_PWA_STATE.registration=reg;
  return reg||null;
}

async function v247GetWorkerDiagnostics(reg){
  const worker=reg?.waiting||reg?.active||reg?.installing||navigator.serviceWorker?.controller;
  if(!worker)return null;
  try{return await v247WorkerMessage(worker,{type:'GET_DIAGNOSTICS'});}catch(err){return {unsupported:true,error:String(err?.message||err)};}
}

async function v247ManifestDiagnostics(report){
  const manifestUrl=new URL('manifest.json',document.baseURI).href;
  try{
    const response=await fetch(manifestUrl,{cache:'no-store'});
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const manifest=await response.json();
    report.manifest=manifest;
    const hasName=!!(manifest.name||manifest.short_name);
    const start=v247ResolveManifestUrl(manifest.start_url,manifestUrl);
    const scope=v247ResolveManifestUrl(manifest.scope||'./',manifestUrl);
    const display=[manifest.display,...(Array.isArray(manifest.display_override)?manifest.display_override:[])].filter(Boolean);
    const installDisplay=display.some(x=>['standalone','minimal-ui','fullscreen','window-controls-overlay'].includes(x));
    const startInScope=!!start&&!!scope&&start.startsWith(scope);
    const icons=Array.isArray(manifest.icons)?manifest.icons:[];
    const icon192=icons.find(x=>String(x.sizes||'').split(/\s+/).includes('192x192'));
    const icon512=icons.find(x=>String(x.sizes||'').split(/\s+/).includes('512x512')&&String(x.purpose||'any').includes('any'))||icons.find(x=>String(x.sizes||'').split(/\s+/).includes('512x512'));
    const valid=hasName&&!!start&&!!scope&&installDisplay&&startInScope&&!!icon192&&!!icon512;
    v247AddCheck(report,'Web app manifest',valid?'pass':'fail',valid?`Loaded · ${manifest.short_name||manifest.name} · ${manifest.display||'display missing'}`:'Missing a required name/start_url/scope/display/192px/512px manifest field');
    if(icon192&&icon512){
      const probes=await Promise.all([v247FetchProbe(v247ResolveManifestUrl(icon192.src,manifestUrl),'icon'),v247FetchProbe(v247ResolveManifestUrl(icon512.src,manifestUrl),'icon')]);
      report.iconProbes=probes;
      const iconsOk=probes.every(x=>x.ok);
      v247AddCheck(report,'Install icons',iconsOk?'pass':'fail',iconsOk?'192×192 and 512×512 icons are reachable':probes.filter(x=>!x.ok).map(x=>`${x.url}: ${x.status||x.error}`).join(' · '));
    }
    if(!startInScope)v247AddCheck(report,'Manifest scope','fail',`start_url ${start||'missing'} is outside scope ${scope||'missing'}`);
    else v247AddCheck(report,'Manifest scope','pass',scope);
  }catch(err){
    v247AddCheck(report,'Web app manifest','fail',String(err?.message||err||'manifest failed'));
  }
}

async function v247RunPwaDiagnostics(options={}){
  if(V247_PWA_DIAGNOSTICS.running)return V247_PWA_DIAGNOSTICS.report;
  V247_PWA_DIAGNOSTICS.running=true;
  V247_PWA_DIAGNOSTICS.error='';
  v244RefreshPwaDom();
  const report={status:'pass',summary:'',startedAt:Date.now(),finishedAt:0,checks:[],failures:0,warnings:0,failedAssets:[],workerVersion:null,cachedCount:0,shellCount:0,missingCached:[]};
  try{
    const secure=!!(window.isSecureContext||location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1');
    v247AddCheck(report,'Secure context',secure?'pass':'fail',secure?`${location.protocol}//${location.host}`:'HTTPS is required for PWA installation');
    const swSupport='serviceWorker' in navigator;
    v247AddCheck(report,'Service worker support',swSupport?'pass':'fail',swSupport?'Supported by this browser':'navigator.serviceWorker is unavailable');

    await v247ManifestDiagnostics(report);

    const swFile=await v247FetchProbe('sw.js','service-worker');
    v247AddCheck(report,'Service worker file',swFile.ok?'pass':'fail',swFile.ok?`HTTP ${swFile.status} · ${swFile.contentType||'content type unavailable'}`:(swFile.status?`HTTP ${swFile.status}`:swFile.error));

    let reg=null;
    if(swSupport&&secure){
      try{reg=await v247WithTimeout(v247GetRegistration(),V247_PWA_TIMEOUT,'service worker registration');}catch(err){V244_PWA_STATE.error=String(err?.message||err);}
    }
    const hasReg=!!reg;
    v247AddCheck(report,'Service worker registration',hasReg?'pass':'fail',hasReg?`Scope: ${reg.scope}`:(V244_PWA_STATE.error||'No registration')); 
    if(reg){
      const lifecycle=reg.waiting?'waiting update':reg.active?.state||reg.installing?.state||'registered';
      v247AddCheck(report,'Worker lifecycle',reg.active||reg.waiting?'pass':'warn',lifecycle);
      const controlled=!!navigator.serviceWorker.controller;
      v247AddCheck(report,'Page controlled by worker',controlled?'pass':'warn',controlled?'Yes':'Not yet — a first successful registration may need one reload');
      const swDiag=await v247GetWorkerDiagnostics(reg);
      report.workerDiagnostics=swDiag;
      if(swDiag&&!swDiag.unsupported){
        report.workerVersion=swDiag.version??null;
        report.cachedCount=Number(swDiag.cachedCount)||0;
        report.shellCount=Number(swDiag.shellCount)||0;
        report.missingCached=Array.isArray(swDiag.missingCached)?swDiag.missingCached:[];
        const cacheOk=report.shellCount>0&&report.missingCached.length===0;
        v247AddCheck(report,'App-shell cache',cacheOk?'pass':'warn',cacheOk?`${report.cachedCount}/${report.shellCount} assets cached`:`${report.cachedCount}/${report.shellCount} cached · ${report.missingCached.length} missing; Repair app cache can retry them`);

        const shell=Array.isArray(swDiag.appShell)?swDiag.appShell:[];
        if(shell.length){
          const probes=await v247MapLimit(shell,6,asset=>v247FetchProbe(asset,'app-shell'));
          report.assetProbes=probes;
          report.failedAssets=probes.filter(x=>!x.ok).map(x=>({url:x.url,status:x.status||0,error:x.error||''}));
          v247AddCheck(report,'Deployed app-shell URLs',report.failedAssets.length?'fail':'pass',report.failedAssets.length?`${report.failedAssets.length}/${shell.length} URLs failed`: `${shell.length}/${shell.length} URLs reachable`);
        }
      }else{
        v247AddCheck(report,'Worker diagnostics','warn',swDiag?.error?'Current worker does not expose v247 diagnostics yet — apply/reload the v247 update first':'No worker diagnostic response');
      }
    }

    const installed=v244PwaStandalone()||V244_PWA_STATE.installed;
    const prompt=!!V244_PWA_STATE.installPrompt;
    v247AddCheck(report,'Native install prompt',installed||prompt?'pass':'warn',installed?'Already installed':prompt?'Browser install prompt is available':'Browser has not exposed beforeinstallprompt. This can be normal on unsupported browsers, after dismissal, or while Chrome still considers a prerequisite unmet.');

    report.finishedAt=Date.now();
    report.status=report.failures?'fail':report.warnings?'warn':'pass';
    report.summary=report.failures?`${report.failures} failed check${report.failures===1?'':'s'}`:report.warnings?`${report.warnings} warning${report.warnings===1?'':'s'}`:'all PWA checks passed';
    V247_PWA_DIAGNOSTICS.report=report;
    V247_PWA_DIAGNOSTICS.lastRunAt=report.finishedAt;
    if(!options.silent){
      try{showToast(report.status==='fail'?`PWA test found ${report.failures} problem${report.failures===1?'':'s'}`:report.status==='warn'?'PWA test passed with warnings':'PWA test passed');}catch(_){ }
    }
    const details=document.getElementById('v247-pwa-diagnostics');
    if(details&&(options.expand!==false||report.status==='fail'))details.open=true;
    return report;
  }catch(err){
    V247_PWA_DIAGNOSTICS.error=String(err?.message||err||'PWA diagnostic failed');
    report.finishedAt=Date.now();report.status='fail';report.summary='diagnostic runner failed';report.failures++;
    V247_PWA_DIAGNOSTICS.report=report;
    if(!options.silent){try{showToast('PWA diagnostics could not finish');}catch(_){ }}
    return report;
  }finally{
    V247_PWA_DIAGNOSTICS.running=false;
    v244RefreshPwaDom();
  }
}

async function v247RepairPwaCache(){
  if(V247_PWA_DIAGNOSTICS.running)return false;
  V247_PWA_DIAGNOSTICS.running=true;V247_PWA_DIAGNOSTICS.error='';v244RefreshPwaDom();
  try{
    const reg=await v247GetRegistration();
    if(!reg)throw new Error('No service worker registration is available');
    await reg.update().catch(()=>{});
    const worker=reg.waiting||reg.active||reg.installing||navigator.serviceWorker.controller;
    const result=await v247WorkerMessage(worker,{type:'RETRY_APP_SHELL_CACHE'},15000);
    if(result?.unsupported)throw new Error(result.error||'The active worker does not support cache repair yet');
    try{showToast(result?.missingCached?.length?`Cache repair finished · ${result.missingCached.length} asset${result.missingCached.length===1?'':'s'} still missing`:'MediaFlow app cache repaired');}catch(_){ }
    return result;
  }catch(err){
    V247_PWA_DIAGNOSTICS.error=String(err?.message||err||'cache repair failed');
    try{showToast('Could not repair the PWA app cache');}catch(_){ }
    return false;
  }finally{
    V247_PWA_DIAGNOSTICS.running=false;
    await v247RunPwaDiagnostics({silent:true,expand:true});
  }
}

const v247InstallPwaBase=v244InstallPwa;
v244InstallPwa=async function(){
  if(v244PwaStandalone()||V244_PWA_STATE.installed)return v247InstallPwaBase.apply(this,arguments);
  if(V244_PWA_STATE.installPrompt)return v247InstallPwaBase.apply(this,arguments);
  await v244RegisterPwa().catch(()=>null);
  if(V244_PWA_STATE.installPrompt)return v247InstallPwaBase.apply(this,arguments);
  const report=await v247RunPwaDiagnostics({silent:true,expand:true});
  if(report?.status==='fail'){
    try{showToast(`Install blocked by ${report.failures} PWA check${report.failures===1?'':'s'} · see PWA Diagnostics`);}catch(_){ }
    const details=document.getElementById('v247-pwa-diagnostics');if(details)details.open=true;
    return false;
  }
  v246PwaInstallHelp();
  return false;
};

window.addEventListener('beforeinstallprompt',()=>{
  V244_PWA_STATE.installPromptSeen=true;
  v244RefreshPwaDom();
});
window.addEventListener('appinstalled',()=>{
  V244_PWA_STATE.installPromptSeen=true;
  v244RefreshPwaDom();
});

App.v244InstallPwa=v244InstallPwa;
App.v244PwaSettingsHtml=v244PwaSettingsHtml;
Object.assign(App,{v247RunPwaDiagnostics,v247RepairPwaCache,v247PwaStatus});
Object.assign(window.MediaFlowPWA,{install:v244InstallPwa,diagnostics:v247RunPwaDiagnostics,repairCache:v247RepairPwaCache,diagnosticState:V247_PWA_DIAGNOSTICS});

MediaFlowRuntime.version=V247_RUNTIME_VERSION;
/* ============================================================
   MediaFlow v248 — Settings Navigation + Managed App Updates
   --------------------------------------------------------------------------
   - Makes the Settings section navigator responsive on desktop and draggable
     horizontally with a mouse/pen whenever it becomes a horizontal strip.
   - Fixes the final APP UPDATES section incorrectly leaving the previous
     Settings item highlighted when the page cannot scroll its heading to the
     old fixed activation anchor.
   - Adds shared, dynamic update-state icons to About, App Updates and the PWA
     install card: checking / behind / update ready / installing / up to date.
   - Adds an Install update flow with staged progress, success/failure feedback,
     service-worker activation, hosted-app fallback refresh and an optional
     persistent automatic-update installation preference.
   - Keeps the v247 PWA diagnostics/cache-repair system intact.
   ============================================================ */
const V248_RUNTIME_VERSION=248;
const V248_UPDATE_INSTALL_STATE={
  running:false,
  progress:0,
  phase:'idle',
  tone:'info',
  message:'',
  target:null,
  startedAt:0,
  finishedAt:0
};
const V248_UPDATE_WAIT_MS=16000;
const V248_UPDATE_RESULT_KEY='mediaflow-v248-update-result';

function v248EnsureUpdateSettings(settings=S.settings){
  if(!settings||typeof settings!=='object')return settings;
  if(typeof settings.autoUpdateCheck!=='boolean')settings.autoUpdateCheck=true;
  if(typeof settings.autoInstallUpdates!=='boolean')settings.autoInstallUpdates=false;
  return settings;
}
if(typeof DEFAULT_SETTINGS.autoInstallUpdates!=='boolean')DEFAULT_SETTINGS.autoInstallUpdates=false;
v248EnsureUpdateSettings(DEFAULT_SETTINGS);
S.settings=S.settings||DEFAULT_SETTINGS;
v248EnsureUpdateSettings(S.settings);

/* ---------- Persistence / preset audit ---------------------------------- */
if(typeof v196NormalizeImportedSettings==='function'){
  const v248NormalizeImportedSettingsBase=v196NormalizeImportedSettings;
  v196NormalizeImportedSettings=function(raw){
    const next=v248NormalizeImportedSettingsBase.apply(this,arguments);
    return v248EnsureUpdateSettings(next);
  };
}
if(typeof v196BuildSettingsPreset==='function'){
  const v248BuildSettingsPresetBase=v196BuildSettingsPreset;
  v196BuildSettingsPreset=function(){
    const preset=v248BuildSettingsPresetBase.apply(this,arguments);
    if(preset?.settings)v248EnsureUpdateSettings(preset.settings);
    preset.presetManifest=preset.presetManifest||{};
    preset.presetManifest.includes=Object.assign({},preset.presetManifest.includes||{}, {
      automaticUpdateInstallPreferenceV248:true,
      currentPersistentSettingsAuditV248:true
    });
    return preset;
  };
}
if(typeof v148BackupManifest==='function'){
  const v248BackupManifestBase=v148BackupManifest;
  v148BackupManifest=function(){
    const manifest=v248BackupManifestBase.apply(this,arguments);
    manifest.includes=Object.assign({},manifest.includes||{}, {
      automaticUpdateInstallPreferenceV248:true,
      managedAppUpdateFlowV248:true,
      settingsPresetAuditV248:true,
      fullExportImportAuditV248:true,
      automaticBackupAuditV248:true,
      syncNowAuditV248:true
    });
    manifest.v248={
      cloudSyncVersion:201,
      fullBackupSchema:29,
      settingsPresetSchema:1,
      personalOrderExportVersion:4,
      newPersistentSetting:'autoInstallUpdates'
    };
    return manifest;
  };
}

/* ---------- Shared update visual state ---------------------------------- */
function v248HasHostedUpdate(){
  const current=Number(v161CurrentVersion())||V248_RUNTIME_VERSION;
  return !!(V161_UPDATE_STATE?.available&&Number(V161_UPDATE_STATE.latest)>current);
}
function v248HasPwaUpdate(){return !!V244_PWA_STATE?.updateReady;}
function v248HasUpdate(){return v248HasHostedUpdate()||v248HasPwaUpdate();}
function v248LatestVersion(){
  const latest=Number(V161_UPDATE_STATE?.latest);
  return Number.isFinite(latest)&&latest>0?latest:null;
}
function v248UpdateVisualState(){
  if(V248_UPDATE_INSTALL_STATE.running){
    if(V248_UPDATE_INSTALL_STATE.phase==='checking')return {id:'checking',tone:'info',label:'Checking for updates'};
    return {id:'installing',tone:'info',label:'Installing update'};
  }
  if(V248_UPDATE_INSTALL_STATE.phase==='success')return {id:'success',tone:'pass',label:V248_UPDATE_INSTALL_STATE.message||'Update installed'};
  if(V248_UPDATE_INSTALL_STATE.phase==='error')return {id:'error',tone:'fail',label:'Update failed'};
  if(V161_UPDATE_STATE?.checking)return {id:'checking',tone:'info',label:'Checking for updates'};
  if(v248HasPwaUpdate())return {id:'ready',tone:'pass',label:'Ready to install'};
  if(v248HasHostedUpdate())return {id:'available',tone:'warn',label:'New update available'};
  if(V161_UPDATE_STATE?.checked&&Number(V161_UPDATE_STATE.latest)>0)return {id:'current',tone:'pass',label:'Up to date'};
  return {id:'idle',tone:'info',label:'Check for updates'};
}

function v248RawIcon(paths,extra=''){
  return `<span class="v248-update-icon ${extra}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths}</svg></span>`;
}
function v248UpdateIconHtml(state=v248UpdateVisualState()){
  switch(state.id){
    case 'checking':
      return v248RawIcon('<path d="M20 7h-5V2"/><path d="M20 7a8 8 0 0 0-14-2"/><path d="M4 17h5v5"/><path d="M4 17a8 8 0 0 0 14 2"/>','is-checking');
    case 'available':
      return v248RawIcon('<path d="M12 3v11"/><path d="m8 10 4 4 4-4"/><path d="M5 18h14"/>','is-available');
    case 'ready':
      return v248RawIcon('<path d="M12 3v10"/><path d="m8 9 4 4 4-4"/><path d="M5 17v3h14v-3"/><path d="m17 5 1.5 1.5L21 4"/>','is-ready');
    case 'installing':
      return v248RawIcon('<path d="M12 3v10"/><path d="m8 9 4 4 4-4"/><path d="M5 18h14"/>','is-installing');
    case 'success':
    case 'current':
      return v248RawIcon('<circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16.5 8.5"/>','is-current');
    case 'error':
      return v248RawIcon('<circle cx="12" cy="12" r="9"/><path d="M12 8v5"/><path d="M12 16h.01"/>','is-error');
    default:
      return v248RawIcon('<path d="M20 7h-5V2"/><path d="M20 7a8 8 0 0 0-14-2"/><path d="M4 17h5v5"/><path d="M4 17a8 8 0 0 0 14 2"/>','is-idle');
  }
}

function v248UpdateStatusText(){
  const current=Number(v161CurrentVersion())||V248_RUNTIME_VERSION;
  const latest=v248LatestVersion();
  if(V248_UPDATE_INSTALL_STATE.running)return V248_UPDATE_INSTALL_STATE.message||'Installing the latest MediaFlow update…';
  if(V248_UPDATE_INSTALL_STATE.phase==='success')return V248_UPDATE_INSTALL_STATE.message||`MediaFlow updated successfully.`;
  if(V248_UPDATE_INSTALL_STATE.phase==='error')return V248_UPDATE_INSTALL_STATE.message||'MediaFlow could not install the update.';
  if(V161_UPDATE_STATE?.checking)return 'Checking the official MediaFlow build…';
  if(v248HasPwaUpdate())return latest&&latest>current?`MediaFlow v${latest} is downloaded and ready to install.`:'A new MediaFlow app update is ready to install.';
  if(v248HasHostedUpdate())return `MediaFlow v${latest} is available. Current build: v${current}.`;
  if(V161_UPDATE_STATE?.checked&&latest)return `You are on the latest detected build (v${current}).`;
  if(V161_UPDATE_STATE?.checked)return `Update check could not verify the hosted build right now. Current build: v${current}.`;
  return `Current build: v${current}. Automatic update checking is ${S.settings?.autoUpdateCheck===false?'off':'on'}.`;
}
function v248UpdateStatusHtml(){
  const state=v248UpdateVisualState();
  return `<span class="v248-inline-update-status is-${state.tone}" data-v248-update-status>${v248UpdateIconHtml(state)}<span>${escapeHtml(v248UpdateStatusText())}</span></span>`;
}
v161UpdateStatusHtml=v248UpdateStatusHtml;

